      "tipo": "GC",
      "causa_raiz": "Alocação massiva de memória na Heap gerenciada (~2.63 MB em um único frame) dentro do método StressTestScene.Update(), provocando pausas síncronas severas do Garbage Collector (17.94ms de GC.Collect). O padrão indica criação de objetos temporários, arrays, listas dinâmicas ou concatenação de strings dentro do ciclo de Update.",
      "codigo_refatorado": "using UnityEngine;
using System.Collections.Generic;

namespace PerformanceAdvisor.StressTest
{
    public class StressTestScene : MonoBehaviour
    {
        [Header("Configurações de Execução")]
        [SerializeField] private int bufferCapacity = 1024;

        // Buffers pré-alocados em memória para evitar alocações dinâmicas no Update
        private int[] _cachedBuffer;
        private List<Vector3> _reusablePositions;
        private readonly System.Text.StringBuilder _stringBuilder = new System.Text.StringBuilder(256);

        private void Awake()
        {
            // Pré-aloca estruturas durante a inicialização (fora da renderização ativa)
            _cachedBuffer = new int[bufferCapacity];
            _reusablePositions = new List<Vector3>(bufferCapacity);
        }

        private void Update()
        {
            // Limpa estruturas existentes sem desalocar da Heap
            _reusablePositions.Clear();
            _stringBuilder.Clear();

            // Execução de lógica frame-a-frame reutilizando a memória existente
            ProcessGameLogic(_reusablePositions, _cachedBuffer);
        }

        private void ProcessGameLogic(List<Vector3> targetList, int[] buffer)
        {
            for (int i = 0; i < buffer.Length; i++)
            {
                buffer[i] = i;
                targetList.Add(new Vector3(i, 0f, 0f));
            }
        }
    }
}",
      "explicacao_didatica": "Quando usamos 'new' ou criamos textos e listas dentro do Update(), a Unity precisa pedir memória nova para o computador a cada fração de segundo. Com o tempo (ou em poucos frames), essa memória temporária enche a lixeira (Heap). O Garbage Collector (GC) é forçado a congelar o jogo para varrer e limpar esse lixo acumulado, causando engasgos (stuttering). A solução é 'alugar' essa memória apenas uma vez no início (Awake/Start) e apenas limpar e reutilizar as mesmas variáveis todo frame com métodos como .Clear(), gerando zero lixo."
    }
  ],
  "dicas_level_design": null
}

